# -*- coding: utf-8 -*-

def blocks():
    return [
        {"t": "p", "text": "ARCHITECT ROADMAP", "size": 12, "bold": True, "center": True, "muted": True},
        {"t": "p", "text": ".NET and Angular", "size": 28, "bold": True, "center": True},
        {"t": "p", "text": "30 days to technical architect", "size": 18, "bold": True, "center": True},
        {"t": "p", "text": "Decisions  ·  Quality attributes  ·  C4 and ADRs  ·  Identity and data", "size": 12, "center": True, "muted": True},
        {"t": "p", "text": "Azure shape  ·  Operability  ·  Frontend boundaries  ·  AI as a critic", "size": 12, "center": True, "muted": True},
        {"t": "p", "text": "For a full-stack developer with about eight years of .NET and Angular delivery who is moving into a technical architect seat.", "size": 12, "italic": True, "center": True},
        {"t": "p", "text": "Prepared 31 October 2026. New work targets .NET 10 LTS, supported through 14 November 2028. .NET 8 and .NET 9 reach end of support in November 2026. For Angular, speak in features you have verified on angular.dev the week you write a standard: standalone components, signals, built-in control flow, and typed forms. Do not memorize a price, a quota, or an Angular major you have not checked.", "size": 11, "center": True, "muted": True},

        {"t": "h1", "text": "What 30 days can actually change"},
        {"t": "p", "text": "Thirty days will not manufacture ten years of architecture tenure. A company still has to give you the seat, and the seat is earned again every quarter by decisions other people can live with. What 30 focused days will do, on top of eight years of shipping .NET and Angular, is close the gap that keeps a strong senior engineer sounding like a senior engineer: you leave with the artifacts, the tradeoff language, and a way of using AI that a technical architect is expected to show."},
        {"t": "p", "text": "By the evening of day 30 you should be able to do five things without notes. Draw the context and the containers for a system you know. Write an architecture decision record that names options, a recommendation, consequences, and a revisit trigger. Turn a quality hope such as 'it must be fast and secure' into a scenario with a number and a window. Lead a one-hour design review without taking the pen. Say what you will not split into microservices, and why."},
        {"t": "warn", "title": "The trap in this title", "text": "Technical architect here means the person who sets and reviews the technical shape of a product estate: boundaries, data ownership, identity, integration, operability, and standards, and who can still read the .NET and Angular. It is not enterprise architect, and it is not a slide role that has left the code. Solution architect, in many services firms, is the same engineering with a heavier workshop, estimate, and stakeholder document. This roadmap trains both rooms. It does not train a vendor-only pre-sales role."},

        {"t": "h2", "text": "How the days are built"},
        {"t": "p", "text": "Each day is about four hours, 120 hours in total. If you only have two hours, cut the external reading first. Do not cut the artifact and do not cut saying the answer out loud. Reading this document quietly will not change how you sound in a review."},
        {"t": "table", "headers": ["Block", "Minutes", "What you do"], "rows": [
            ["Study", "70", "Read that day's explanation in this document until you can restate it."],
            ["External source", "30", "Read only the section named for that day. Stop when the timer ends."],
            ["Artifact", "70", "Write the page, diagram, or decision in your own words."],
            ["Speak", "30", "Say the Say this box in under two minutes. Then say the failure mode."],
            ["AI critic", "30", "Run that day's prompt. Reject anything you cannot defend. Edit the artifact."],
            ["Redraw", "10", "Close the laptop picture. Redraw the decision from memory on paper."],
        ]},
        {"t": "note", "title": "Where this sits next to your other guides", "text": "The 10-day tech lead roadmap and the deep dive are the depth spike: C#, ASP.NET Core, EF Core, SQL, Azure hosts, and a first microservices pass. The further 20 days cover pipelines, MVC, and AI-assisted delivery. This 30-day document does not repeat those lessons. When a panel drops into a coding or LINQ question, use those guides. When they ask what you decided and what you gave up, use this one."},

        {"t": "h2", "text": "The 30 days"},
        {"t": "table", "headers": ["Day", "You practice", "Artifact before sleep"], "rows": [
            ["1", "The seat, and how it differs from senior and tech lead", "Positioning line and a stakeholder map"],
            ["2", "Quality attributes and scenarios", "Three scenarios for the sample system"],
            ["3", "C4 and a short architecture description", "Context and container diagrams"],
            ["4", "Architecture decision records", "ADR-001 modular monolith"],
            ["5", "Boundaries, language, and team shape", "Context map on one page"],
            ["6", "Angular and .NET reference shape, including the BFF", "Request path and auth notes"],
            ["7", "Week review", "Principles, one page, edited after an AI critique"],
            ["8", "Integration styles and contracts", "Sync versus async table for the sample flows"],
            ["9", "Data ownership, tenancy, outbox", "Schema ownership sketch"],
            ["10", "Consistency, duplicates, sagas", "Order state machine and one compensation"],
            ["11", "Identity and threat modeling", "STRIDE notes on submit order"],
            ["12", "Azure shape and Well-Architected", "Host decision table"],
            ["13", "API as a contract", "Status-code and idempotency rules"],
            ["14", "Week review", "ADR-002 messaging, plus the threat model"],
            ["15", "SLOs, timeouts, retries, bulkheads", "SLO sheet"],
            ["16", "Observability from browser to SQL", "What you log, measure, and page on"],
            ["17", "Cost and capacity without invented prices", "Assumption and cost-driver page"],
            ["18", "Evolutionary architecture and strangler", "One migration slice with rollback"],
            ["19", "Angular architecture at this altitude", "ADR-003 frontend composition"],
            ["20", "Governance a team will accept", "Review triggers and a 15-item radar"],
            ["21", "Week review", "Ten-minute architecture briefing, spoken"],
            ["22", "Case: design from a one-page brief", "Containers, data, accept path, one failure"],
            ["23", "Case: legacy modernization", "One-page plan a director can fund"],
            ["24", "Case: notify, audit, and search", "Three stores, three reasons"],
            ["25", "Writing for a stakeholder", "Decision memo: why not microservices this half"],
            ["26", "Facilitating a review", "Agenda and the questions you will ask"],
            ["27", "Portfolio", "README plus five stories from your own career"],
            ["28", "Mock architecture interview", "Scored notes from a 45-minute design"],
            ["29", "Repair the weak spot", "Second case: a partner API"],
            ["30", "First 90 days in the seat", "Listening tour and the first fitness function"],
        ]},

        {"t": "h1", "text": "Who you are in the review"},
        {"t": "p", "text": "You have eight years of delivery. You have shipped Angular screens and .NET APIs. You have felt a release go wrong. The architect interview fails when that history comes out as a list of frameworks. It lands when it comes out as a decision: the constraint, the option you rejected, the consequence, and the signal that would make you reopen it."},
        {"t": "lead", "title": "Positioning line", "text": "I have about eight years as a full-stack .NET and Angular developer. I am moving into a technical architect role. I still go deep on the API, the data access, and the SPA, and I now own the shape around them: boundaries, quality attributes, identity, and how we operate the system. I decide with a tradeoff, a consequence, and a revisit trigger. I do not split a system into services because a diagram looks modern."},
        {"t": "h2", "text": "What changes between the seats"},
        {"t": "table", "headers": ["They ask", "Senior full-stack answer", "Technical architect answer"], "rows": [
            ["Microservices?", "How I would call the other service.", "The business capability, the data owner, the team that deploys it, the failure the user sees, and why a module is enough until those are real."],
            ["How should the Angular app authenticate?", "An interceptor and a token in storage.", "Who the users are, where the token lives, what a stolen script can do, and whether a backend for frontend removes the token from the browser."],
            ["The page is slow.", "A missing index or a heavy bundle.", "The budget, which percentile, which request is on the user path, and which delay we moved to a message on purpose."],
            ["Can we rewrite the legacy app?", "The target framework.", "The slice that earns the rewrite, the people who query the old database, the rollback, and the date the old path dies."],
            ["Which Azure service?", "The service I used last year.", "The operational load, the scale assumption, the identity, and the pillar it stresses: reliability, security, cost, operations, or performance."],
        ]},
        {"t": "h2", "text": "Answer shape that scores as an architect"},
        {"t": "b", "numbered": True, "items": [
            "First sentence: the decision, not the background.",
            "Second beat: the constraint that made it (team size, data ownership, latency, threat, cost driver).",
            "Third beat: the option you rejected and the pain it would have added.",
            "Fourth beat: how you would know the decision is failing. A metric, an incident, or a date.",
            "Stop. If they lean in, give one story from your eight years. If you do not know a limit, name the document or the bill you would open. Invented numbers lose the room.",
        ]},
        {"t": "h2", "text": "Score each artifact from 0 to 2"},
        {"t": "b", "items": [
            "Decision: a reader can see what you chose.",
            "Tradeoff: you named what you gave up.",
            "Operable: a person on call can see how it fails and how it rolls back.",
            "Evidence: a scenario, a diagram, or a number you labeled as an assumption or a measurement.",
            "Six points out of eight is a hire signal on that artifact. A correct diagram with no rejected option still sounds like a senior developer.",
        ]},

        {"t": "h1", "text": "The system you will design all month"},
        {"t": "p", "text": "Harbor is a B2B wholesale portal. Buyer companies place orders. Internal staff release credit holds and watch fulfillment exceptions. You will not build Harbor as a product this month. You will make the architecture decisions a team of about eight to twelve engineers could build."},
        {"t": "p", "text": "Label these numbers as assumptions every time you say them. If a panel changes a number, change the design. Peak is about 40 order submits a second. About 2,000 buyer companies and 15,000 users. The accept path, meaning the order is durable before the API returns, targets p95 under 400 milliseconds. Email and other notices can take a minute. One Azure region until an SLO forces a second region. Card numbers stay at the payment provider. You do not store them. The team is two squads that can still talk every day. A million events a second is a different system. Do not design that system by accident."},
        {"t": "h2", "text": "The containers you are allowed to use"},
        {"t": "b", "items": [
            "Buyer portal and ops portal: Angular. They may be two apps or two areas. Day 19 forces the choice.",
            "A backend for frontend, the BFF: ASP.NET Core. The browser's only API.",
            "Harbor application: a modular monolith on ASP.NET Core with modules for Catalog, Ordering, and Billing, until an ADR splits one out.",
            "Azure SQL: one database, schema per module, unless a later decision says otherwise.",
            "Azure Service Bus: something that must survive a process restart and may be handled twice.",
            "A notification worker: Azure Functions, isolated worker, because mail is a different failure domain from the accept path.",
            "Microsoft Entra ID for staff. Microsoft Entra External ID for buyers on a new system. Azure AD B2C only if you are extending an estate that already has it.",
            "Key Vault and managed identity. No passwords in appsettings, and nothing secret in the Angular environment files. Those files ship to the browser.",
        ]},
        {"t": "note", "title": "Repo to create on day 1", "text": "Create a private git repository named harbor-architecture. Folders: docs/principles, docs/c4, docs/adr, docs/quality, docs/security, docs/reviews. Write markdown. Diagrams can be Mermaid or a photo of a page. This repository is the portfolio. Do not put real customer data, secrets, or your employer's private designs in it."},

        {"t": "h1", "text": "How to use AI for 30 days without handing it the decision"},
        {"t": "p", "text": "AI is a critic and a drafter in this plan. It is not the architect. Cursor, in this repository, is the right tool because it can see your ADR next to your principles. A chat window is the right tool for a mock panel. Copilot is fine for a code sketch inside a depth spike. The failure mode is a fluent document you cannot redraw the next morning."},
        {"t": "h2", "text": "Rules you do not break"},
        {"t": "b", "numbered": True, "items": [
            "Paste the constraints before the question: team size, scale assumption, one region, no card data, .NET and Angular, existing database if any.",
            "Ask for the strongest objection and the missing quality attribute. Do not ask 'is this a good architecture'.",
            "You write the decision sentence yourself. The model may propose options you then accept or reject.",
            "Throw away invented prices, quotas, latency numbers, and legal claims. If a number matters, label it assumption or name the calculator, the bill, or the official limit.",
            "Do not paste secrets, production connection strings, personal data, or unreleased financials. Use a company-approved tenant when the material is work material.",
            "Redraw from memory after every AI session. If you cannot, the model owns the design and you do not.",
            "Check any large sample for a license you do not have. Prefer your own Harbor names over a pasted textbook diagram.",
        ]},
        {"t": "h2", "text": "Session prompt, paste at the start of every AI block"},
        {"t": "code", "text": """You are a staff-level reviewer of a .NET and Angular system called Harbor, a B2B wholesale portal.
Constraints: about 8 to 12 engineers, about 40 order submits per second at peak (assumption), one Azure region, Azure SQL, no card data stored, buyers on Entra External ID, staff on Entra ID, Angular portals, ASP.NET Core on .NET 10.
Your job is to attack my draft. Do not rewrite it unless I ask.
Reply in this order:
1. The decision you think I actually made, in one sentence.
2. The strongest objection.
3. The quality attribute I ignored (name the stimulus and the missing measure).
4. What fails at 2 a.m., and whether rollback is real.
5. One option I did not consider, and when it would be better.
Do not invent Azure prices, quotas, or benchmark numbers. If a limit matters, name the document I should open.
Mark any sentence I should not say out loud because it is vague."""},
        {"t": "p", "text": "Each day adds a shorter prompt aimed at that day's artifact. Run the session prompt first, then the day's prompt, on the text you wrote yourself. If you let the model write the first draft, you must delete it and write the decision sentence again before you score the day."},
        {"t": "h2", "text": "Where Cursor fits"},
        {"t": "b", "items": [
            "Keep principles.md open. Ask Cursor to list sentences in the ADR that contradict a principle. You decide which side to change.",
            "Ask for a Mermaid container diagram from your own container list. Then draw it on paper without looking.",
            "Ask for a hostile review of a pull request that breaks module boundaries. That is the tech-lead spike, still useful on days 18 and 20.",
            "Do not ask Cursor to 'design Harbor properly' and then commit the answer. That produces a portfolio you cannot defend.",
        ]},
        {"t": "warn", "title": "What the model must not decide", "text": "Whether you promise 99.99 percent. Whether you adopt Kubernetes. Whether you are in scope for a regulation. Whether a rewrite is funded. Whether a person on your team is ready to own a service. Those are your decisions, made with people who carry the cost."},

        {"t": "h1", "text": "Materials"},
        {"t": "p", "text": "This document is the primary study material. External sources are there so you can see the original wording of an idea. You do not buy a course. You do not watch a 40-hour video series during these 30 days."},
        {"t": "h2", "text": "Have these open"},
        {"t": "b", "items": [
            ".NET 10 SDK, so any sketch you write still compiles.",
            "Current Node LTS and the Angular CLI major you have decided to speak about.",
            "A markdown editor. The repository above.",
            "Paper. The interview and the review still happen on a whiteboard.",
            "Optional: Docker if you want .NET Aspire locally in week 3. Not required to finish the 30 days.",
            "An Azure subscription is optional. Draw the hosts. Do not spend the month in the portal.",
        ]},
        {"t": "h2", "text": "Books, used as references, not as a reading challenge"},
        {"t": "table", "headers": ["Source", "Use it for", "Time you should spend"], "rows": [
            ["Fundamentals of Software Architecture, Richards and Ford", "Characteristics, decisions, and what not to diagram", "About 4 hours, days 1 to 4"],
            ["Software Architecture: The Hard Parts, Ford, Richards, Sadalage, Dehghani", "Data ownership, granularity, sagas", "About 4 hours, days 9 and 10"],
            ["Designing Data-Intensive Applications, Kleppmann", "Chapters 1, 7, and 8 only: reliability, transactions, distributed-system trouble", "About 5 hours, days 10 and 15"],
            ["Team Topologies, Skelton and Pais", "Four team types and three interaction modes", "About 2 hours, day 5"],
            ["Building Evolutionary Architectures, Ford, Parsons, Kua", "Fitness functions", "About 2 hours, day 18"],
            ["Release It!, Nygard, second edition", "Timeouts, bulkheads, and stability patterns", "About 3 hours, day 15"],
            ["Accelerate, Forsgren, Humble, Kim", "The four delivery metrics, as health of the system not as a slogan", "About 90 minutes, day 20"],
            ["Site Reliability Engineering, free at sre.google", "Embracing Risk, and Service Level Objectives", "About 2 hours, day 15"],
        ]},
        {"t": "h2", "text": "Free primary sources"},
        {"t": "b", "items": [
            "Azure Well-Architected Framework and the Azure Architecture Center, on Microsoft Learn. Pillars and the application-architecture decision guides.",
            "Microsoft identity platform documentation: authorization code flow with PKCE, and the on-behalf-of flow so you know when not to use it.",
            "ASP.NET Core security and OpenAPI documentation. Problem Details. Cookie and OpenID Connect handlers.",
            ".NET Aspire overview, so you can say what it does locally and what it does not decide in production.",
            "angular.dev: signals, standalone components, lazy routes, and the releases page for the support window.",
            "c4model.com for diagram levels. adr.github.io and Michael Nygard's original ADR post for the decision format.",
            "arc42, the short template, as a checklist when a document feels bloated. You do not fill all twelve sections for Harbor.",
            "OWASP API Security Top 10, current edition. Especially broken object level authorization.",
            "Google's SRE book chapters named above. ISO/IEC 25010 only as a checklist of quality names, not as the way you speak.",
        ]},
        {"t": "p", "text": "If a book is not on your shelf, the explanation in this document is enough to do the day's artifact. The book makes you harder to shake in a follow-up question. Do not stall the calendar waiting for a delivery."},
        {"t": "break"},
    ]
